<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Throwable; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Illuminate\Support\Facades\Log; use Illuminate\Contracts\Http\Kernel; use Illuminate\Support\Facades\Facade; class PanelApi { private ?User $actor = null; public function __construct(private readonly User $user, private readonly ?string $ip = null) { } public function get(string $path, array $query = []): PanelResponse { return $this->send('GET', $path, $query); } public function post(string $path, array $body = [], array $query = []): PanelResponse { return $this->send('POST', $path, $query, $this->encode($body)); } public function put(string $path, array $body = []): PanelResponse { return $this->send('PUT', $path, [], $this->encode($body)); } public function delete(string $path, array $body = []): PanelResponse { return $this->send('DELETE', $path, [], $body === [] ? null : $this->encode($body)); } public function raw(string $path, array $query, string $content): PanelResponse { return $this->send('POST', $path, $query, $content, 'text/plain'); } private function encode(array $body): string { return json_encode($body === [] ? new \stdClass() : $body, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE); } private function send(string $method, string $path, array $query = [], ?string $content = null, string $type = 'application/json'): PanelResponse { $url = url('/api/client/' . ltrim($path, '/')); if ($query !== []) { $url .= '?' . http_build_query($query); } $request = Request::create($url, $method, [], [], [], [ 'HTTP_ACCEPT' => 'application/json', 'CONTENT_TYPE' => $type, 'HTTP_USER_AGENT' => 'Stark AI Companion', 'REMOTE_ADDR' => $this->ip ?? '127.0.0.1', ], $content); $app = app(); $previous = $app->bound('request') ? $app->make('request') : null; $auth = $app->make('auth'); $guard = $auth->getDefaultDriver(); $auth->forgetGuards(); $auth->guard('web')->setUser($this->actor()); try { $response = $app->make(Kernel::class)->handle($request); $body = (string) $response->getContent(); $decoded = json_decode($body, true); return new PanelResponse($response->getStatusCode(), is_array($decoded) ? $decoded : null, $body); } catch (Throwable $exception) { Log::warning('ai: in-process client API call failed', ['path' => $path, 'error' => $exception->getMessage()]); return new PanelResponse(500, null, ''); } finally { $auth->forgetGuards(); $auth->shouldUse($guard); if ($previous !== null) { $app->instance('request', $previous); Facade::clearResolvedInstance('request'); } } } private function actor(): User { return $this->actor ??= (User::query()->find($this->user->id) ?? $this->user); } } 